/**
 * Where a 365 day lives outside PIM: its Audius track and its YouTube video.
 *
 * audius_map.json is generated by scripts/audius/sync_audius.mjs.
 * youtube_map.json maps a day number to a YouTube video id or URL, e.g.
 *   { "47": "dQw4w9WgXcQ" }. Days without an entry show no YouTube button.
 */
import audiusMap from '@/data/audius_map.json';
import youtubeMap from '@/data/youtube_map.json';

interface AudiusEntry {
  day: number | null;
  url: string;
  status: string;
  alt?: boolean;
}

export const AUDIUS_PROFILE_URL = `https://audius.co/${audiusMap.handle}`;

// The main upload wins over an alt (earlier) upload of the same song.
const audiusByDay = new Map<number, string>();
for (const t of audiusMap.tracks as AudiusEntry[]) {
  if (t.status !== 'matched' || t.day == null) continue;
  if (!t.alt || !audiusByDay.has(t.day)) audiusByDay.set(t.day, t.url);
}
for (const t of audiusMap.tracks as AudiusEntry[]) {
  if (t.status === 'matched' && t.day != null && !t.alt) audiusByDay.set(t.day, t.url);
}

export function getAudiusUrl(day: number): string | null {
  return audiusByDay.get(day) ?? null;
}

const YT_ID = /^[A-Za-z0-9_-]{11}$/;

/** Accepts a bare id or any youtube.com / youtu.be link; returns the 11-char id. */
export function parseYouTubeId(value: string): string | null {
  const v = value.trim();
  if (YT_ID.test(v)) return v;
  try {
    const u = new URL(v);
    if (u.hostname === 'youtu.be') return YT_ID.test(u.pathname.slice(1)) ? u.pathname.slice(1) : null;
    if (u.hostname.endsWith('youtube.com')) {
      const id = u.searchParams.get('v') ?? u.pathname.split('/').filter(Boolean).pop() ?? '';
      return YT_ID.test(id) ? id : null;
    }
  } catch {
    /* not a URL */
  }
  return null;
}

export function getYouTubeId(day: number): string | null {
  const raw = (youtubeMap as Record<string, string>)[String(day)];
  return raw ? parseYouTubeId(raw) : null;
}
